-- ============================================================================
-- Migration 0229: Seed the marketing closed loop (AEO + SEO)
-- Generated by scripts/generate-marketing-seed.mjs (deterministic, re-runnable).
--   AEO questions : 754 (published, themed to "the AI Family Operating System")
--   SEO keywords  : 191
--   SEO pages     : 19
-- The public FAQ / Knowledge Center + each blog article read the PUBLISHED
-- AEO rows, so this is the single source that feeds every public page.
-- Idempotent (delete-by-seed-tag then insert / ON CONFLICT). Requires 0013.
-- ============================================================================

DELETE FROM public.marketing_aeo_questions WHERE metadata->>'seed' = 'aeo_v1';

ON CONFLICT (keyword, target_path) DO NOTHING;

ON CONFLICT (path) DO UPDATE SET title = EXCLUDED.title, meta_description = EXCLUDED.meta_description, status = EXCLUDED.status, score = EXCLUDED.score, last_audited_at = EXCLUDED.last_audited_at, metadata = EXCLUDED.metadata;

-- Seeded: 754 AEO questions, 191 SEO keywords, 19 SEO pages.
