INSERT INTO public.marketing_seo_pages (path, title, meta_description, status, score, last_audited_at, metadata) VALUES
('/', 'Bubaly — The AI Family Operating System', 'One shared home for your family’s calendar, chores, meals, money, and documents — with an AI assistant that takes real action. Start free.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/features', 'Features — The AI Family Operating System | Bubaly', 'Shared calendar, chores, meal planning, family wallet, documents, and an AI assistant that does the work. See everything Bubaly does.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/how-it-works', 'How Bubaly Works — Your AI Family Operating System', 'Set it up once and let Bubaly run the logistics: ask the AI assistant in plain language and it creates real events, lists, chores, and reminders.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/ai', 'The Bubaly AI Assistant — It Takes Action, Not Just Chats', 'Bubaly’s AI assistant turns plain-language requests into real calendar events, chores, meal plans, grocery lists, and reminders for your whole family.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/pricing', 'Pricing — The AI Family Operating System | Bubaly', 'Start free, no credit card required. See Bubaly’s plans for families who want the whole household in one shared, AI-driven system.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/mobile', 'Bubaly on Mobile — Your Family OS Everywhere', 'Bubaly is an installable app with native iOS and Android companions — your family operating system on every device.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/security', 'Security & Privacy — Bubaly', 'Every family’s data is isolated with row-level security; documents are private and served via short-lived signed URLs. Privacy is a feature, not a footnote.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/faq', 'FAQ & Family Knowledge Center — Bubaly', 'Answers to the questions families ask about organizing family life with an AI Family Operating System — privacy, roles, the AI assistant, pricing, and more.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/blog', 'The Bubaly Blog — Tips, Stories & Insights for Modern Families', 'Practical advice for organizing family life: parenting, meals, money, school, wellness, travel, and the AI Family Operating System.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
('/contact', 'Contact Bubaly', 'Questions about the AI Family Operating System? Get in touch with the Bubaly team.', 'active', 92, now(), jsonb_build_object('seed','seo_v1')),
